source = INTEGRATION.read_text(encoding="utf-8")
anchor = '''    def revoke_entries(\n'''
helper = '''    def disable_features(self, entry_ids) -> int:\n        """Atomically turn manor/fishing off for the supplied launch entries.\n\n        Crop, quantity and fishing profile selections are intentionally retained\n        so the user can re-enable individual roles later without rebuilding them.\n        """\n        wanted = []\n        seen = set()\n        for raw in entry_ids:\n            entry_id = str(raw or "").strip()\n            if entry_id and entry_id not in seen:\n                seen.add(entry_id)\n                wanted.append(entry_id)\n        if not wanted:\n            return 0\n\n        with self._lock:\n            previous = {str(key): dict(value) for key, value in self.settings.items()}\n            changed = []\n            for entry_id in wanted:\n                row = self.setting(entry_id)\n                if bool(row.get("manor_enabled", False)) or bool(row.get("fishing_enabled", False)):\n                    row["manor_enabled"] = False\n                    row["fishing_enabled"] = False\n                    changed.append(entry_id)\n            if not changed:\n                return 0\n            try:\n                self._save_settings()\n            except Exception:\n                self.settings = previous\n                raise\n            manor_pairs = [\n                self.manors.get(entry_id) for entry_id in changed\n                if self.manors.get(entry_id) is not None\n            ]\n            live = []\n            for entry_id in changed:\n                record = self.records.get(entry_id)\n                worker = self.workers.get(record.hwnd) if record else None\n                if record is not None and worker is not None and worker.is_alive():\n                    live.append((entry_id, record, worker))\n\n        for pair in manor_pairs:\n            manager, _lifetime_stop = pair\n            try:\n                manager.cancel_current()\n            except Exception:\n                LOG.exception("failed to cancel manor during batch disable")\n\n        for entry_id, record, worker in live:\n            try:\n                current = self.binding_loader(entry_id).get(record.hwnd)\n                if current is not None:\n                    worker.apply_binding(current, announce=False)\n            except Exception:\n                LOG.exception("failed to apply batch-disabled automation settings")\n        return len(changed)\n\n'''
if source.count(anchor) != 1:
    raise SystemExit(f"batch-disable integration anchor count={source.count(anchor)}")
source = source.replace(anchor, helper + anchor, 1)
INTEGRATION.write_text(source, encoding="utf-8", newline="\n")

