helper = '''    def disable_all_automation_for_current_group(self) -> None:\n        entries = tuple(self.current_group().launch_entries)\n        entry_ids = tuple(str(entry.entry_id or "").strip() for entry in entries)\n        entry_ids = tuple(entry_id for entry_id in entry_ids if entry_id)\n        if not entry_ids:\n            self.write_log("本組沒有可關閉的莊園／釣魚角色。")\n            return\n        try:\n            changed = int(self.automation.disable_features(entry_ids))\n        except Exception as exc:\n            self.write_log(f"本組莊園／釣魚全部關閉失敗：{exc}")\n            messagebox.showwarning(\n                "自動重連", "本組莊園／釣魚未能完整關閉；原設定保持不變。"\n            )\n            return\n        self.automation_manor_enabled.set(False)\n        self.automation_fishing_enabled.set(False)\n        selected_id = self.automation_selected_entry_id\n        if selected_id and selected_id in entry_ids:\n            self.load_automation_editor(selected_id)\n        self.refresh_automation_rows()\n        if changed:\n            self.write_log(\n                f"本組已一次關閉 {changed} 個角色的莊園／釣魚；作物、數量與魚級設定保留。"\n            )\n        else:\n            self.write_log("本組莊園／釣魚原本已全部關閉。")\n\n'''
