anchor = '''class StrictRegistryTests(unittest.TestCase):\n'''
case = '''class BatchAutomationDisableTests(unittest.TestCase):\n    @staticmethod\n    def controller(settings):\n        ctl = object.__new__(EmbeddedAutomationController)\n        ctl._lock = threading.RLock()\n        ctl.settings = {str(key): dict(value) for key, value in settings.items()}\n        ctl.manors = {}\n        ctl.records = {}\n        ctl.workers = {}\n        ctl._save_settings = mock.Mock()\n        return ctl\n\n    def test_batch_disable_is_atomic_and_preserves_choices(self):\n        ctl = self.controller({\n            "a": {\n                "manor_enabled": True, "manor_crop_key": "rare_tree",\n                "manor_quantity": 7, "fishing_enabled": True,\n                "fishing_profile_id": "fish-5",\n            },\n            "b": {\n                "manor_enabled": False, "manor_crop_key": "normal_rock",\n                "manor_quantity": 16, "fishing_enabled": True,\n                "fishing_profile_id": "fish-7",\n            },\n        })\n        changed = ctl.disable_features(("a", "b", "a"))\n        self.assertEqual(changed, 2)\n        ctl._save_settings.assert_called_once_with()\n        self.assertFalse(ctl.settings["a"]["manor_enabled"])\n        self.assertFalse(ctl.settings["a"]["fishing_enabled"])\n        self.assertEqual(ctl.settings["a"]["manor_crop_key"], "rare_tree")\n        self.assertEqual(ctl.settings["a"]["manor_quantity"], 7)\n        self.assertEqual(ctl.settings["a"]["fishing_profile_id"], "fish-5")\n        self.assertFalse(ctl.settings["b"]["manor_enabled"])\n        self.assertFalse(ctl.settings["b"]["fishing_enabled"])\n        self.assertEqual(ctl.settings["b"]["fishing_profile_id"], "fish-7")\n\n    def test_batch_disable_rolls_back_every_role_on_save_failure(self):\n        original = {\n            "a": {"manor_enabled": True, "fishing_enabled": True},\n            "b": {"manor_enabled": True, "fishing_enabled": False},\n        }\n        ctl = self.controller(original)\n        ctl._save_settings.side_effect = OSError("disk blocked")\n        with self.assertRaises(OSError):\n            ctl.disable_features(("a", "b"))\n        self.assertEqual(ctl.settings, original)\n\n    def test_ui_exposes_current_group_all_off_button(self):\n        source = (Path(__file__).parent / "flash_sync_v02.py").read_text(encoding="utf-8")\n        self.assertIn('text="本組全部關閉"', source)\n        self.assertIn('command=self.disable_all_automation_for_current_group', source)\n        self.assertIn('self.automation.disable_features(entry_ids)', source)\n        self.assertIn('作物、數量與魚級設定保留', source)\n\n\n'''
if test.count(anchor) != 1:
    raise SystemExit(f"batch-disable test anchor count={test.count(anchor)}")
test = test.replace(anchor, case + anchor, 1)
